import { test } from "node:test";
import assert from "node:assert/strict";
import { create } from "../src/store.mjs";

test("R1 create size 0", () => {
  assert.equal(create().size(), 0);
});

test("R2 set then get, unknown key undefined", () => {
  const s = create();
  s.set("a", 1);
  assert.equal(s.get("a"), 1);
  assert.equal(s.get("nope"), undefined);
});

test("R3 remove then get undefined, unknown remove safe", () => {
  const s = create();
  s.set("a", 1);
  s.remove("a");
  assert.equal(s.get("a"), undefined);
  assert.doesNotThrow(() => s.remove("never"));
});

test("R1-R3 hold together", () => {
  const s = create();
  s.set("x", 1);
  s.set("y", 2);
  assert.equal(s.size(), 2);
  s.remove("x");
  assert.equal(s.size(), 1);
  assert.equal(s.get("y"), 2);
});
